SELECT p.id AS periodId, p.title, p.year, p.total_amount AS totalAmount, p.used_amount AS usedAmount, (p.total_amount - p.used_amount) AS remainAmount, ROUND(p.used_amount / NULLIF(p.total_amount, 0) * 100, 2) AS executionRate, p.start_date AS startDate, p.end_date AS endDate, p.status, p.public_time AS publicTime FROM budget_period p WHERE p.is_public = 1 AND p.status <> 0 AND p.deleted = 0
AND p.year = #{year}
AND p.status = #{status}
ORDER BY p.start_date DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM budget_period p WHERE p.is_public = 1 AND p.status <> 0 AND p.deleted = 0
AND p.year = #{year}
AND p.status = #{status}
